"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Second backbone: model-internal diagnostics of the two backbone differences (2026-11-25; design written down
before computing; dev only, descriptive; changes no frozen file, setting, threshold or read-out and
reads no test or replication data).

D1  does timing survive pooling?
    d1       scripts/p1v4_ears_time_diag.py probe (poolings whole / seg3 / last1 / sec8; standardised features,
             LogisticRegression C = 0.1; group all-right at the 0.5 cut with the package's cluster bootstrap) and the
             post-hoc shuffled-seconds control of p1v4_ears_time_control.py (same procedure; only its output path is
             changed here), with the folders redirected per backbone. Train: the diagnostic's 24,944 train windows
             (backbone 1's ears_time/feats_train.npz gives the ids, parts and answers); backbone 2's per-second ears
             of the same window ids come from runs_bb2/grounding/allclass2d/sec8_train.npz (command prep). Dev: each
             backbone's per-second ears of every dev window (backbone 1 ears_time/feats_dev.npz, backbone 2
             runs_bb2/ears_time/feats_dev.npz from its natural dev forward; the audio tokens do not depend on the text).
             Backbone 2's seconds hold 12 or 13 audio tokens (12.5 per second), backbone 1's 13.
    offsets  decode the decision offset (door onset 0.5 / 1.0 / 1.5 / 2.0 s before the window end) of the 72 dev
             S-move groups' offset windows (backbone 1: runs_bb2/offsets/dev_bb1, from the offsets code check;
             backbone 2: runs_bb2/offsets/dev) from the pooled ears (mean and max over the window) and from the
             per-second ears; 4 classes, chance 0.25; version 1 (knock, footsteps, door) primary, versions 1 and 3
             (footsteps and door, with or without the knock) secondary.
D2  audio information in the language model's option states without labels: dev grounding condition "none"
    (grounding/dev/l1_none.npz, one question per window: R on the R-hear windows, S on the S-move windows). Versions:
    R-hear 1 ring, 2 nothing, 3 decoy; S-move 1 knock then footsteps and door (the user leaves), 2 knock only,
    3 footsteps and door without the knock, 4 television. Per part a decision probe (version 1 against the others)
    and pair probes (version 1 against one other version); out-of-fold within-group concordance (version 1 scored
    above the other version of the same group; ties half) and AUC. Features: the option states (2 x hidden) and, as a
    reference, the pooled ears; each at full width and reduced to 64 principal components fitted inside each
    training fold (equal capacity across widths 6,144 and 2,048).
CV (offsets, D2): the units shuffled into 5 folds with seed s = 0..4 (the same folds on both backbones; all windows
of a unit in one fold); StandardScaler (+ PCA) + LogisticRegression C = 0.1, max_iter 2000.
Commands (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/bb2_diag.py
  prep        backbone 2's diagnostic train file and dev copy -> data/p1v4/runs_bb2/ears_time_diag/
  d1 bb1|bb2  -> results/main_v04_bb2/diag_ears_time_dev_<bb>.json, diag_ears_time_control_dev_<bb>.json
              (bb1: also compared with the stored results/main_v04/ears_time_{diag,control}_dev.json)
  offsets     -> results/main_v04_bb2/diag_offset_decoding_dev.json
  d2          -> results/main_v04_bb2/diag_states_probe_dev.json
Every command prints the files it read under data/p1v4/runs and results/main_v04 (Audit).
"""
import collections
import json
import os
import shutil
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

BB = {"bb1": "data/p1v4/runs", "bb2": "data/p1v4/runs_bb2"}
RES1, RES2 = "results/main_v04", "results/main_v04_bb2"
DIAG2 = "data/p1v4/runs_bb2/ears_time_diag"
SEC8_TRAIN2 = "data/p1v4/runs_bb2/grounding/allclass2d/sec8_train.npz"
OFFS = {"bb1": "data/p1v4/runs_bb2/offsets/dev_bb1", "bb2": "data/p1v4/runs_bb2/offsets/dev"}
SEEDS, FOLDS, NPC = (0, 1, 2, 3, 4), 5, 64
VERS = {"r_hear": ("1", "2", "3"), "s_move": ("1", "2", "3", "4")}


class Audit:
    """Records the files opened under the first backbone's run and results folders."""

    def __enter__(self):
        import builtins
        self.paths, self._open, self._load = [], builtins.open, np.load

        def opn(f, *a, **k):
            self.paths.append(str(f))
            return self._open(f, *a, **k)

        def load(f, *a, **k):
            self.paths.append(str(f))
            return self._load(f, *a, **k)
        builtins.open, np.load = opn, load
        return self

    def __exit__(self, *exc):
        import builtins
        builtins.open, np.load = self._open, self._load
        ps = sorted({p.replace("\\", "/") for p in self.paths})
        print("read under data/p1v4/runs:", json.dumps([p for p in ps if p.startswith(BB["bb1"] + "/")], indent=1))
        print("read under results/main_v04:", json.dumps([p for p in ps if p.startswith(RES1 + "/")], indent=1),
              flush=True)
        return False


# ------------------------------------------------------------------------------------------------ D1: ears over time

def prep():
    """Backbone 2's per-second ears of the diagnostic's train windows (ids, parts, answers from backbone 1's file)."""
    os.makedirs(DIAG2, exist_ok=True)
    a = open(f"{SEC8_TRAIN2[:-4]}.sha256.athena.txt").read().split()[0]
    b = open(f"{SEC8_TRAIN2[:-4]}.sha256.local.txt").read().split()[0]
    assert a == b, "sec8_train.npz differs from Athena's"
    tr1 = np.load(f"{BB['bb1']}/ears_time/feats_train.npz")
    ids = tr1["ids"]
    z = np.load(SEC8_TRAIN2)
    pos = {i: n for n, i in enumerate(z["ids"])}
    idx = np.array([pos[i] for i in ids])
    sm = z["sec_mean"][idx]
    sx = z["sec_max"][idx]
    np.savez(f"{DIAG2}/feats_train.npz", ids=ids, parts=tr1["parts"], y=tr1["y"], sec_mean=sm, sec_max=sx)
    shutil.copy2(f"{BB['bb2']}/ears_time/feats_dev.npz", f"{DIAG2}/feats_dev.npz")
    # information only: the whole-window mean and max rebuilt from the seconds against the stored pooled ears
    dv = np.load(f"{DIAG2}/feats_dev.npz")
    g = np.load(f"{BB['bb2']}/grounding/dev/l1_none.npz")
    drow = {i: n for n, i in enumerate(dv["ids"])}
    r = [drow[i] for i in g["ids"]]
    smd, sxd = dv["sec_mean"][r].astype(np.float32), dv["sec_max"][r].astype(np.float32)
    d = g["ears"].shape[1] // 2
    st = g["ears"].astype(np.float32)
    check = {"train": {"n_windows": int(len(ids)), "sha256": a},
             "dev": {"n_matched": len(r), "max_abs_max_rebuilt_vs_stored": float(np.abs(sxd.max(1) - st[:, d:]).max()),
                     "max_abs_mean_rebuilt_vs_stored": float(np.abs(smd.mean(1) - st[:, :d]).max()),
                     "note": "backbone 2's seconds hold 12 or 13 tokens, so the mean of the second means is not the "
                             "token mean exactly; the max is; the stored pooled ears come from the batch-1 grounding "
                             "forward, the seconds from the batch-8 natural forward"}}
    json.dump(check, open(f"{DIAG2}/check.json", "w"), indent=1)
    print(json.dumps(check, indent=1), flush=True)


def control(out_path):
    """= p1v4_ears_time_control.main with the output path as an argument (same features, permutation, probe)."""
    from sklearn.linear_model import LogisticRegression
    import p1v4_ears_time_control as EC
    import p1v4_ears_time_diag as ET
    import p1v4_grounding as G
    import p1v4_grounding_report as GR
    tr = np.load(f"{ET.OUT}/feats_train.npz")
    dv = np.load(f"{ET.OUT}/feats_dev.npz")
    drow = {i: n for n, i in enumerate(dv["ids"])}
    rows, _ = G.load("dev")
    groups = G.load_groups("dev")
    cl = GR.cluster_table(rows, "dev")
    diag = json.load(open(ET.RES))
    res = {"note": "post hoc, added after seeing the diagnostic", "parts": {}}
    for part, task in ET.TASK.items():
        m = (tr["parts"] == part) & (tr["y"] >= 0)
        sm_tr, sx_tr, y = tr["sec_mean"][m].astype(np.float32), tr["sec_max"][m].astype(np.float32), tr["y"][m]
        gs = [g for g in groups if g["part"] == part]
        units = [g["unit"] for g in gs]
        vers = diag["parts"][part]["versions"]
        flat = [drow[f"{g['unit']}|{v}|{g['k']}"] for g in gs for v in vers]
        sm_dv, sx_dv = dv["sec_mean"][flat].astype(np.float32), dv["sec_max"][flat].astype(np.float32)
        ev = 1 if task == "S" else 0
        v1 = vers.index("1")
        others = [j for j in range(len(vers)) if j != v1]
        out = {}
        for name, keep_last in (("sec8 shuffled", False), ("sec8 last kept", True)):
            rng = np.random.default_rng(0)
            a_tr = ET.pool(*EC.permute(sm_tr, sx_tr, keep_last, rng), "sec8")
            a_dv = ET.pool(*EC.permute(sm_dv, sx_dv, keep_last, rng), "sec8")
            mu, sd = a_tr.mean(0), a_tr.std(0) + 1e-6
            t0 = time.time()
            clf = LogisticRegression(C=0.1, max_iter=2000).fit((a_tr - mu) / sd, y)
            p1 = clf.predict_proba((a_dv - mu) / sd)[:, 1]
            sc = (p1 if ev == 1 else 1 - p1).reshape(len(gs), len(vers))
            r = ((sc[:, v1] >= 0.5) & np.all(sc[:, others] < 0.5, 1)).astype(float)
            c = GR.criterion(units, cl, {}, lambda w, a=r: GR.wmean(w, a), lambda a=r: float(a.mean()))
            out[name] = {"group_all_right_0.5": c["point"], "ci95": c["ci95"],
                         "auc_v1_vs_others": ET.auc(sc[:, v1], sc[:, others].ravel()),
                         "hit_v1_0.5": float(np.mean(sc[:, v1] >= 0.5)),
                         "false_alarm_0.5": {vers[j]: float(np.mean(sc[:, j] >= 0.5)) for j in others},
                         "fit_s": round(time.time() - t0, 1)}
            print(f"{part} {name:15s} all-right {c['point']:.3f} [{c['ci95'][0]:.3f}, {c['ci95'][1]:.3f}] AUC "
                  f"{out[name]['auc_v1_vs_others']:.3f}", flush=True)
        out["for reference (diagnostic)"] = {k: diag["parts"][part]["poolings"][k]["group_all_right_0.5"]
                                             for k in ET.POOLINGS}
        res["parts"][part] = out
    json.dump(res, open(out_path, "w"), indent=1)
    return res


def d1(bb):
    import p1v4_ears_time_diag as ET
    import p1v4_grounding as G
    import p1v4_grounding_report as GR
    if bb == "bb2":
        ET.OUT = DIAG2
        G.R = GR.R = BB["bb2"]
    ET.RES = f"{RES2}/diag_ears_time_dev_{bb}.json"
    os.makedirs(RES2, exist_ok=True)
    ET.probe()
    ctl = control(f"{RES2}/diag_ears_time_control_dev_{bb}.json")
    if bb == "bb1":                                    # the code check against the stored first-backbone results
        new, old = json.load(open(ET.RES)), json.load(open(f"{RES1}/ears_time_diag_dev.json"))
        worst = max(abs(new["parts"][p]["poolings"][k][f] - old["parts"][p]["poolings"][k][f])
                    for p in old["parts"] for k in old["parts"][p]["poolings"]
                    for f in ("group_all_right_0.5", "auc_v1_vs_others", "hit_v1_0.5"))
        ci = max(abs(a - b) for p in old["parts"] for k in old["parts"][p]["poolings"]
                 for a, b in zip(new["parts"][p]["poolings"][k]["ci95"], old["parts"][p]["poolings"][k]["ci95"]))
        oc = json.load(open(f"{RES1}/ears_time_control_dev.json"))
        wc = max(abs(ctl["parts"][p][k][f] - oc["parts"][p][k][f]) for p in oc["parts"]
                 for k in ("sec8 shuffled", "sec8 last kept") for f in ("group_all_right_0.5", "auc_v1_vs_others"))
        print(f"code check vs stored backbone-1 diagnostic: max |diff| {worst:.2e} (CI ends {ci:.2e}); "
              f"control {wc:.2e}", flush=True)


# ------------------------------------------------------------------------------------------------ shared CV probe

def folds_of(units, seed):
    order = np.random.default_rng(seed).permutation(sorted(set(units)))
    return {u: n % FOLDS for n, u in enumerate(order)}


def oof(X, y, units, seed, npc=None):
    """Out-of-fold P(class) for a grouped 5-fold CV (binary: P(1); multiclass: the class probabilities)."""
    from sklearn.decomposition import PCA
    from sklearn.linear_model import LogisticRegression
    from sklearn.preprocessing import StandardScaler
    fold = folds_of(units, seed)
    f = np.array([fold[u] for u in units])
    ncls = len(np.unique(y))
    P = np.zeros((len(y), ncls))
    for k in range(FOLDS):
        tr, te = f != k, f == k
        sc = StandardScaler().fit(X[tr])
        a, b = sc.transform(X[tr]), sc.transform(X[te])
        if npc:
            p = PCA(n_components=npc, svd_solver="full", random_state=0).fit(a)
            a, b = p.transform(a), p.transform(b)
        clf = LogisticRegression(C=0.1, max_iter=2000).fit(a, y[tr])
        P[te] = clf.predict_proba(b)
    return P[:, 1] if ncls == 2 else P


def auc(pos, neg):
    pos, neg = np.asarray(pos), np.asarray(neg)
    return float(((pos[:, None] > neg[None, :]) + 0.5 * (pos[:, None] == neg[None, :])).mean())


def summary(vals):
    v = np.array(vals, dtype=float)
    return {"mean": float(v.mean()), "min": float(v.min()), "max": float(v.max())}


# ------------------------------------------------------------------------------------------------ D1: offsets

def offsets():
    import p1v4_readout_2d as R2D
    res = {"note": "decode the decision offset (door onset before the window end) from the ears; grouped 5-fold CV "
                   "by unit, seeds 0-4; chance 0.25", "offsets_after_door_onset_s": [1.0 + d for d in R2D.OFFSETS],
           "backbones": {}}
    for bb in ("bb1", "bb2"):
        z = {d: np.load(f"{OFFS[bb]}/l1_d{d:+.1f}.npz") for d in R2D.OFFSETS}
        out = {}
        for sel_name, keep in (("version 1", ("1",)), ("versions 1 and 3", ("1", "3"))):
            X = {"pooled ears": [], "per-second ears": []}
            y, units = [], []
            for c, d in enumerate(R2D.OFFSETS):
                for n, i in enumerate(z[d]["ids"]):
                    u, v, _ = str(i).split("|")
                    if v not in keep:
                        continue
                    X["pooled ears"].append(z[d]["ears"][n].astype(np.float32))
                    X["per-second ears"].append(np.concatenate([z[d]["sec_mean"][n].ravel(),
                                                                z[d]["sec_max"][n].ravel()]).astype(np.float32))
                    y.append(c)
                    units.append(u)
            y = np.array(y)
            out[sel_name] = {"n": int(len(y))}
            for feat, rows in X.items():
                A = np.stack(rows)
                for width, npc in (("full", None), (f"pca{NPC}", NPC)):
                    accs, mae = [], []
                    for s in SEEDS:
                        P = oof(A, y, units, s, npc)
                        pred = P.argmax(1)
                        accs.append(float(np.mean(pred == y)))
                        mae.append(float(np.mean(np.abs(pred - y))) * 0.5)
                    out[sel_name][f"{feat} {width}"] = {"n_features": int(A.shape[1]), "accuracy": summary(accs),
                                                        "mean_abs_error_s": summary(mae)}
                    print(f"{bb} {sel_name:16s} {feat:15s} {width:5s} accuracy {np.mean(accs):.3f} "
                          f"[{min(accs):.3f}, {max(accs):.3f}] MAE {np.mean(mae):.2f} s", flush=True)
        res["backbones"][bb] = out
    json.dump(res, open(f"{RES2}/diag_offset_decoding_dev.json", "w"), indent=1)


# ------------------------------------------------------------------------------------------------ D2: states

def d2():
    res = {"note": "option states and pooled ears of the dev condition none (no labels in the text); grouped 5-fold "
                   "CV by unit, seeds 0-4; within-group concordance of version 1 against each other version",
           "versions": {"r_hear": "1 ring, 2 nothing, 3 decoy",
                        "s_move": "1 knock then footsteps and door, 2 knock only, 3 footsteps and door without the "
                                  "knock, 4 television"},
           "backbones": {}}
    for bb in ("bb1", "bb2"):
        z = np.load(f"{BB[bb]}/grounding/dev/l1_none.npz")
        assert (z["q_win"] == np.arange(len(z["q_win"]))).all()      # one question per window
        uv = [str(i).split("|") for i in z["ids"]]
        out = {}
        for part, vers in VERS.items():
            m = np.array([str(p) == part for p in z["parts"]])
            idx = np.where(m)[0]
            units = [uv[i][0] for i in idx]
            ver = np.array([uv[i][1] for i in idx])
            probes = {"decision: 1 vs others": vers[1:]}
            probes.update({f"pair: 1 vs {v}": (v,) for v in vers[1:]})
            o = {}
            for feat in ("states", "ears"):
                F = z[feat][idx].astype(np.float32)
                for width, npc in (("full", None), (f"pca{NPC}", NPC)):
                    for pname, neg in probes.items():
                        keep = np.isin(ver, ("1",) + tuple(neg))
                        uu = [u for u, k in zip(units, keep) if k]
                        vv = ver[keep]
                        y = (vv == "1").astype(int)
                        conc = {v: [] for v in neg}
                        aucs = {v: [] for v in neg}
                        for s in SEEDS:
                            p = oof(F[keep], y, uu, s, npc)
                            by = collections.defaultdict(dict)
                            for u, v, q in zip(uu, vv, p):
                                by[u][v] = q
                            for v in neg:
                                pairs = [(d["1"], d[v]) for d in by.values() if "1" in d and v in d]
                                conc[v].append(float(np.mean([(a > b) + 0.5 * (a == b) for a, b in pairs])))
                                aucs[v].append(auc([a for a, _ in pairs], [b for _, b in pairs]))
                        o[f"{feat} {width} | {pname}"] = {
                            "n_features": int(F.shape[1]),
                            "concordance": {f"1 vs {v}": summary(conc[v]) for v in neg},
                            "auc": {f"1 vs {v}": summary(aucs[v]) for v in neg}}
                        print(f"{bb} {part} {feat:6s} {width:5s} {pname:22s} " + "  ".join(
                            f"1v{v} conc {np.mean(conc[v]):.3f} AUC {np.mean(aucs[v]):.3f}" for v in neg), flush=True)
            out[part] = o
        res["backbones"][bb] = out
    json.dump(res, open(f"{RES2}/diag_states_probe_dev.json", "w"), indent=1)


if __name__ == "__main__":
    a = sys.argv[1:]
    with Audit():
        if a == ["prep"]:
            prep()
        elif a and a[0] == "d1" and len(a) == 2 and a[1] in BB:
            d1(a[1])
        elif a == ["offsets"]:
            offsets()
        elif a == ["d2"]:
            d2()
        else:
            raise SystemExit(__doc__)
